mapper.select:
SELECT b.board_id::TEXT AS row_id, b.name AS board_name, b.type_cd, c.name AS board_cd_name, b.description, b.list_cnt, b.file_yn, b.file_cnt_limit, b.file_size_limit_mb, b.notice_yn, b.new_cnt, b.use_yn FROM board b LEFT JOIN code c ON c.code_id = b.type_cd AND c.p_code_id = 'BOARD00' WHERE b.use_yn = 'Y'
AND b.name LIKE '%' || #{filterKeyword} || '%'
ORDER BY b.board_id DESC LIMIT #{pageSize} OFFSET #{offset}
